function applyCourseTheme(){const course=courseInfo();themeKey=course.id+course.accent;document.documentElement.style.setProperty('--cyan',course.accent);document.documentElement.style.setProperty('--blue',course.secondary);if(world){world.background.set(course.sky);world.fog.color.set(course.fog);world.traverse(o=>{if(o.isPointLight)o.color.set(course.accent);else if(o.isDirectionalLight)o.color.set(course.secondary)})}if(stars)stars.material.color.set(course.secondary);if(planetMesh){if(planetTexture)planetTexture.dispose();planetTexture=makePlanetTexture(course.kind);planetMesh.material.map=planetTexture;planetMesh.material.color.set('#ffffff');planetMesh.material.emissive.set(course.accent);planetMesh.material.needsUpdate=true}if(planetRings){planetRings.material.color.set(course.accent);planetRings.visible=course.kind==='jupiter'||course.tags?.includes('rings')}routeEdgeLines.forEach((line,i)=>line.material.color.set(i?course.secondary:course.accent));if(speedStreaks)speedStreaks.material.color.set(course.accent);if(finishGate)finishGate.traverse(o=>{if(o.material?.color)o.material.color.set(course.accent)});if(worldEnv&&world){const look=worldEnv.apply(course);if(stars)stars.material.opacity=.8*look.starOpacity;if(planetMesh)planetMesh.visible=false;if(planetRings)planetRings.visible=false}}
