async function finishHeat(){const r=state.race;const performanceScore=Math.max(0,Math.floor(r.score+r.laps*300+Math.max(0,r.hull)*35));r.finalScore=performanceScore;const rp=Math.round(24+performanceScore/65);const credits=Math.round(35+performanceScore/50);state.totalScore+=performanceScore;state.rp+=rp;state.credits+=credits;if(r.courseFinishTime!==null){const previous=Number(state.bestTimes[state.courseId])||Infinity;if(r.courseFinishTime<previous){state.bestTimes[state.courseId]=r.courseFinishTime;r.newPB=true;const sticker=`pb-${state.courseId}`;if(!state.stickers.includes(sticker))state.stickers.push(sticker)}}saveProfile();drawHome();try{await api('complete',{code:state.code,playerId:state.playerId,result:{playerId:state.playerId,score:performanceScore,heat:state.heat,flightTime:r.courseFinishTime??60+r.time}});const room=await api('get',{code:state.code,method:'GET'});state.room=room.room}catch{}showResults(state.heat>=3);startPolling();}
