function drawShipArt(ship){return `<div class="ship-art"><svg viewBox="0 0 180 100" aria-label="${ship.name} ship illustration"><defs><linearGradient id="shipg" x1="0" x2="1"><stop stop-color="#182c41"/><stop offset=".5" stop-color="${ship.color}" stop-opacity=".85"/><stop offset="1" stop-color="#182c41"/></linearGradient></defs><path d="M90 12 L112 48 L164 68 L135 78 L105 68 L90 90 L75 68 L45 78 L16 68 L68 48 Z" fill="url(#shipg)" stroke="${ship.color}" stroke-width="2"/><ellipse cx="90" cy="49" rx="13" ry="19" fill="${ship.color}" opacity=".8"/><ellipse cx="90" cy="45" rx="7" ry="10" fill="#e6fff9"/><path d="M83 71 L90 99 L97 71" fill="${ship.color}" opacity=".72"/></svg></div>`}
function openGarage(){state.selected=state.ship;renderGarage();showScreen('garage-screen')}
function renderGarage(){const ship=SHIPS.find(s=>s.id===state.selected)||SHIPS[0],stats=shipStats(ship.id);$('ship-picker').innerHTML=SHIPS.map(s=>`<button class="ship-option ${s.id===ship.id?'selected':''}" data-ship="${s.id}"><strong>${s.name}</strong><small>${state.owned.includes(s.id)?(s.id===state.ship?'ACTIVE · ':'')+s.class:`${s.cost} ✧`}</small></button>`).join('');$('ship-picker').querySelectorAll('button').forEach(b=>b.onclick=()=>{state.selected=b.dataset.ship;renderGarage()});$('ship-detail').innerHTML=[['SPEED',stats.speed],['HANDLING',stats.handling],['HULL',stats.hull],['FUEL',stats.fuel]].map(([label,val])=>`<div class="stat-block"><small>${label}</small><strong>${val}</strong><div class="statbar"><i style="width:${Math.min(100,val)}%"></i></div></div>`).join('');buildMicroShip(stats);$('ship-art-slot').innerHTML=drawShipArt(ship);const owned=state.owned.includes(ship.id);$('module-picker').innerHTML=MODULES.map(m=>{const unlocked=state.unlockedModules.includes(m.id),equipped=(state.upgrades[ship.id]||'stock')===m.id;return`<button class="module-option ${equipped?'selected':''} ${unlocked?'':'locked'}" data-module="${m.id}"><strong>${m.name}</strong><small>${unlocked?m.description:`${m.cost} ✧ · ${m.description}`}</small></button>`}).join('');$('module-picker').querySelectorAll('button').forEach(button=>button.onclick=()=>{const module=MODULES.find(m=>m.id===button.dataset.module);if(!owned){toast('Unlock this hull before tuning it.');return}if(!state.unlockedModules.includes(module.id)){if(state.credits<module.cost){toast(`Need ${module.cost-state.credits} more credits for this module.`);return}state.credits-=module.cost;state.unlockedModules.push(module.id);toast(`${module.name} unlocked`)}state.upgrades[ship.id]=module.id;saveProfile();drawHome();renderGarage()});$('select-ship').querySelector('span:first-child').textContent=owned?(state.ship===ship.id?'ACTIVE SHIP':'SELECT SHIP'):`UNLOCK · ${ship.cost} CREDITS`;$('select-ship').onclick=()=>{if(owned){state.ship=ship.id;saveProfile();drawHome();renderGarage();toast(`${ship.name} selected`);return}if(state.credits<ship.cost){toast(`Need ${ship.cost-state.credits} more credits to unlock this hull.`);return}state.credits-=ship.cost;state.owned.push(ship.id);state.ship=ship.id;state.selected=ship.id;saveProfile();renderGarage();drawHome();toast(`${ship.name} joined your fleet`)}}

document.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>showScreen('home-screen'));$('solo-button').onclick=()=>createLobby(true);$('copy-code').onclick=shareInvite;document.querySelectorAll('#lobby-screen [data-home],#results-screen [data-home]').forEach(b=>b.addEventListener('click',exitRoom));$('create-button').onclick=()=>createLobby(false);$('join-button').onclick=joinLobby;$('join-code').addEventListener('keydown',e=>{if(e.key==='Enter')joinLobby()});$('join-code').addEventListener('input',e=>e.target.value=e.target.value.toUpperCase().replace(/[^A-Z0-9]/g,''));$('forge-world').onclick=updateCourseFromPrompt;$('world-prompt').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();updateCourseFromPrompt()}});$('course-prev').onclick=()=>selectCourse(-1);$('course-next').onclick=()=>selectCourse(1);$('start-button').onclick=startMatch;$('bots-minus').onclick=()=>setBots(state.botCount-1);$('bots-plus').onclick=()=>setBots(state.botCount+1);$('garage-button').onclick=openGarage;
window.addEventListener('keydown',e=>{const active=state.previousView==='race-screen';if(active&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown',' ','w','W','a','A','s','S','d','D'].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.code==='Space')$('boost-button').classList.add('active')});window.addEventListener('keyup',e=>{keys[e.key]=false;if(e.code==='Space')$('boost-button').classList.remove('active')});$('boost-button').onpointerdown=e=>{e.preventDefault();keys.Space=true;$('boost-button').classList.add('active')};$('boost-button').onpointerup=$('boost-button').onpointerleave=()=>{keys.Space=false;$('boost-button').classList.remove('active')};let touchX=null,touchY=null;$('race-screen').addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||e.target.closest('button'))return;touchX=e.clientX;touchY=e.clientY;e.currentTarget.setPointerCapture?.(e.pointerId)});$('race-screen').addEventListener('pointermove',e=>{if(touchX===null)return;const dx=e.clientX-touchX,dy=e.clientY-touchY;if(state.race){state.race.x=THREE.MathUtils.clamp(state.race.x+dx*.022*state.race.handling,-5.35,5.35);state.race.y=THREE.MathUtils.clamp(state.race.y-dy*.02*state.race.handling,-3.7,3.7);state.race.touchSteer=Math.max(-1,Math.min(1,dx/24));state.race.touchLift=Math.max(-1,Math.min(1,-dy/24))}else if(state.freeFlight){state.freeFlight.vx+=dx*.45;state.freeFlight.vy-=dy*.45}touchX=e.clientX;touchY=e.clientY});$('race-screen').addEventListener('pointerup',()=>{touchX=touchY=null;if(state.race){state.race.touchSteer=0;state.race.touchLift=0}});$('race-screen').addEventListener('pointercancel',()=>{touchX=touchY=null;if(state.race){state.race.touchSteer=0;state.race.touchLift=0}});window.starwakeStartFreeFlight=startFreeFlight;window.starwakeStopFreeFlight=stopFreeFlight;window.starwakeCreateLobby=createLobby;window.starwakeJoinLobby=joinLobby;window.addEventListener('starwake:start-freeflight',event=>startFreeFlight(event.detail?.seed));window.addEventListener('starwake:stop-freeflight',stopFreeFlight);window.addEventListener('starwake:open-race',event=>createLobby(event.detail?.mode!=='pvp'));window.addEventListener('starwake:select-course',event=>{const detail=event.detail||{},prompt=String(detail.prompt||'').trim().slice(0,120),forged=normalizeCourseDefinition(detail.course);if(forged){registerCourse(forged);state.forgedCourse=forged}const course=COURSES.find(item=>item.id===detail.courseId)||courseFromPrompt(prompt);state.courseId=course.id;state.coursePrompt=prompt;state.courseSeed=Number.isFinite(Number(detail.seed))&&Number(detail.seed)!==0?Number(detail.seed)>>>0:coursePromptSeed(prompt||course.id);saveProfile();drawHome();renderRefinements()});
loadProfile();$('pilot-name').value=localStorage.getItem('starwake-name')||'Pilot 01';$('world-prompt').value=state.coursePrompt||'';initFlightScene();drawHome();renderRefinements();$('sound-toggle').onclick=()=>{state.audio=!state.audio;toast(state.audio?'Audio cues enabled':'Audio cues muted')};
